// stages them in LDS — the second half of what its name means.
func DNOperandsInRegisters(k DNKernel) bool {
	v, _ := dnVariantFor(k)
	return v.qkreg
}

// DNPrefetches says whether a rung issues the next token's operands before
// the current token's arithmetic.
func DNPrefetches(k DNKernel) bool {
	v, _ := dnVariantFor(k)
	return v.prefetch
}

// InPort is the layer's input as the fused projection's A operand wants it:
// fp16 [T][lda], `hc_mixed` narrowed. The row count is the arena's, not the
// run's, because the GEMM rungs have no bounds check and the rows between the
// prompt and the row block have to carry the products of zeros.
func (g *DeltaNetGPU) InPort() Port {
	return Port{Buf: g.hbuf, Off: g.hXn, Stride: g.lda, Width: g.cfg.NEmbd,
		Rows: g.arenaRows, Half: true}
}

// OutPort is the layer's output, `linear_attn_out`: fp32 [T][nEmbd].
func (g *DeltaNetGPU) OutPort() Port {
	return Port{Buf: g.abuf, Off: g.aResult, Stride: g.cfg.NEmbd, Width: g.cfg.NEmbd}
}
	for _, p := range g.pipes {
		p.Destroy()
	}
	for _, m := range g.mods {
		m.Destroy()
	}
	for _, b := range []*vk.Buffer{g.hbuf, g.abuf, g.wbuf, g.wbank} {
		if b != nil {
			b.Destroy()
		}
	}
}

// InPort is the layer's input as the fused projection's A operand wants it:
// fp16 [T][lda], `hc_mixed` narrowed.
func (g *AttnGPU) InPort() Port {
	return Port{Buf: g.hbuf, Off: g.hXn, Stride: g.lda, Width: g.cfg.NEmbd,
		Rows: g.arenaRows, Half: true}
}

// OutPort is the layer's output, `attn_output`: fp32 [T][nEmbd].
#version 450

#extension GL_EXT_shader_16bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable


layout(binding = 0) readonly buffer Src { float src[]; };
layout(binding = 1) buffer Dst32 { float dst32[]; };
layout(binding = 2) buffer Dst16 { float16_t dst16[]; };

layout(push_constant) uniform PC {
    uint srcOff;    // float offset of source row 0
    uint dstOff;    // float or half offset of destination row 0
    uint rows;      // rows that carry values
    uint padRows;   // rows to write; [rows, padRows) get zeros
    uint width;     // values in a row
    uint srcStride; // floats between source rows
    uint dstStride; // elements between destination rows
    uint narrow;    // 1 = write halves through dst16, 0 = floats through dst32
} pc;

layout(local_size_x = 256) in;

void main() {
    uint t = gl_WorkGroupID.x;
    if (t >= pc.padRows) {
        return;
    }
    // Uniform across the workgroup, so the branch below is a branch per
    // dispatch and not per element.
    bool live = t < pc.rows;
    uint s = pc.srcOff + t * pc.srcStride;
    uint d = pc.dstOff + t * pc.dstStride;
    for (uint i = gl_LocalInvocationID.x; i < pc.width; i += gl_WorkGroupSize.x) {
        float v = live ? src[s + i] : 0.0;
        if (pc.narrow != 0u) {
            dst16[d + i] = float16_t(v);
        } else {
            dst32[d + i] = v;
        }
    }
}

