// once a run.
func (g *DeltaNetGPU) Past() int { return g.past }

// SetPast places the next run's first token at position n.
func (g *DeltaNetGPU) SetPast(n int) error {
	if n < 0 {
		return fmt.Errorf("llm: position %d", n)
	}
	g.past = n
	g.writeSeq()
	}
	g.rows = nTok
