import re
p='backend/llm.go'; s=open(p).read()
a=s.index('	// The default is **4096** (P12).')
b=s.index('	Batch int\n')
new='''	// The default is **4096** (P12), and since P16 it is **free**. P12-7
	// measured it through the server as a trade — 1.12x on prefill for 0.92x
	// on decode, breaking even at ~150 generated tokens — and that decode
	// cost was a bug: the DeltaNet and attention input ports padded a decode
	// step's one row with zeros out to the whole arena, once a layer. With
	// the port padded to its row block, the same measurement (four distinct
	// ~3.9-4.3k-token prompts at ctx 8192, 256 generated, two passes
	// agreeing to 0.1%) reads:
	//
	//	2048   1052.2 tok/s prefill    34.19 tok/s decode
	//	4096   1198.5          1.14x   34.20
	//	8192   1232.5          1.17x   34.16
	//
	// So a wider batch is now a question of memory and nothing else: 8192
	// helps only prompts longer than 4096 tokens (946 against 886 tok/s at
	// 128k, P14), costs ~3 GB more arena than 4096, and lowers the
	// maxStorageBufferRange cap on the context. Arenas, at ctx 4096: 2.28 GB
	// at 2048 against 3.78 at 4096.
'''
s=s[:a]+new+s[b:]
open(p,'w').write(s)

p='cmd/serve/main.go'; s=open(p).read()
old='''			"P12, through this server: 2048 is 1021 tok/s prefill and 28.0 decode, 4096 is 1146 (1.12x) and 25.8 (0.92x). "+
			"The wider arenas cost 8% of decode, so 4096 wins total latency below ~150 generated tokens and loses above it")'''
new='''			"P16, through this server: 2048 is 1052 tok/s prefill, 4096 is 1199 (1.14x), 8192 is 1233, and decode is 34.2 at all three. "+
			"Wider costs only memory: 8192 helps prompts past 4096 tokens and holds ~3 GB more")'''
assert old in s; s=s.replace(old,new); open(p,'w').write(s)

p='API.md'; s=open(p).read()
a=s.index('**`-llm-batch` is 4096 and it is a trade, not a free win** (P12).')
b=s.index('for interactive turns.', a)+len('for interactive turns.')
new='''**`-llm-batch` is 4096, and a wider batch costs memory and nothing else**
(P16). Measured through this server on four ~3.9-4.3k-token prompts, 256
generated tokens, two passes agreeing to 0.1%: 2048 prefills at **1052
tok/s**, 4096 at **1199** (1.14x, ~0.5 s off the time to first token) and
8192 at **1233**, and all three **decode at 34.2 tok/s**. (P12 measured 4096
costing 8% of decode; that was a bug, fixed in P16.) 8192 is only faster on
prompts longer than 4096 tokens, holds ~3 GB more arena, and lowers the
longest `-llm-ctx` the attention cache can reach, so it is the setting for a
deployment whose prompts are long.'''
s=s[:a]+new+s[b:]
s=s.replace('    -llm-batch       4096         tokens the prefill arenas hold (P12; 2048 trades TTFT for decode)',
            '    -llm-batch       4096         tokens the prefill arenas hold (P16: wider costs memory only)')
open(p,'w').write(s)
EOF
